import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    # Factor each A_i, collecting the exponent of each prime on each edge.
    primes = {}
    for i, value in enumerate(a):
        x = value
        d = 2
        while d * d <= x:
            if x % d == 0:
                e = 0
                while x % d == 0:
                    x //= d
                    e += 1
                primes.setdefault(d, []).append((i, e))
            d += 1 if d == 2 else 2
        if x > 1:
            primes.setdefault(x, []).append((i, 1))

    answer = 1
    for p, edges in primes.items():
        edge_exp = [0] * (n - 1)
        total = 0
        for i, e in edges:
            edge_exp[i] = e
            total += e

        # Heights are the p-adic exponents in the sequence, normalized so
        # their minimum is zero. Count walks that remain nonnegative and touch 0.
        limit = total
        pw = [1] * (limit + 1)
        for h in range(1, limit + 1):
            pw[h] = pw[h - 1] * p % MOD

        untouched = [0] * (limit + 1)
        touched = [0] * (limit + 1)
        touched[0] = 1
        for h in range(1, limit + 1):
            untouched[h] = pw[h]

        for i, e in enumerate(edge_exp):
            nu = [0] * (limit + 1)
            nt = [0] * (limit + 1)
            for h in range(limit + 1):
                u = untouched[h]
                t = touched[h]
                if e == 0:
                    if u:
                        nu[h] = u * pw[h] % MOD
                    if t:
                        nt[h] = t * pw[h] % MOD
                else:
                    if u:
                        nh = h + e
                        if nh <= limit:
                            nu[nh] = (nu[nh] + u * pw[nh]) % MOD
                        nh = h - e
                        if nh >= 0:
                            val = u * pw[nh] % MOD
                            if nh == 0:
                                nt[0] = (nt[0] + val) % MOD
                            else:
                                nu[nh] = (nu[nh] + val) % MOD
                    if t:
                        nh = h + e
                        if nh <= limit:
                            nt[nh] = (nt[nh] + t * pw[nh]) % MOD
                        nh = h - e
                        if nh >= 0:
                            nt[nh] = (nt[nh] + t * pw[nh]) % MOD
            untouched, touched = nu, nt

        factor = sum(touched) % MOD
        answer = answer * factor % MOD

    print(answer)

if __name__ == '__main__':
    main()

