from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)

        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, idx))

        largest = second = count_largest = 0
        largest_owner = -1
        gains = [0] * m
        base = 0

        for right in range(1, n + 1):
            for a, idx in buckets[right]:
                if a > largest:
                    second = largest
                    largest = a
                    count_largest = 1
                    largest_owner = idx
                elif a == largest:
                    count_largest += 1
                elif a > second:
                    second = a

            base += right - largest
            if count_largest == 1 and largest_owner != -1:
                gains[largest_owner] += largest - second

        return base + max(gains)

