import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    edges = [None] + [(next(it)-1, next(it)-1, next(it)) for _ in range(m)]
    queries = []
    closed = [False] * (m+1)
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it)
            queries.append((1, e))
            closed[e] = True
        else:
            queries.append((2, next(it)-1, next(it)-1))

    inf = 10**30
    d = [[inf] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for e in range(1, m+1):
        if not closed[e]:
            u, v, w = edges[e]
            d[u][v] = d[v][u] = w

    for k in range(n):
        rk = d[k]
        for i in range(n):
            dik = d[i][k]
            if dik < inf:
                ri = d[i]
                for j in range(n):
                    nd = dik + rk[j]
                    if nd < ri[j]:
                        ri[j] = nd

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            _, x, y = query
            val = d[x][y]
            answers.append(str(val if val < inf else -1))
        else:
            _, e = query
            u, v, w = edges[e]
            du = [d[i][u] for i in range(n)]
            dv = [d[i][v] for i in range(n)]
            row_u = d[u][:]
            row_v = d[v][:]
            for i in range(n):
                row = d[i]
                a = du[i] + w
                b = dv[i] + w
                for j in range(i, n):
                    val1 = a + row_v[j]
                    val2 = b + row_u[j]
                    if val2 < val1:
                        val1 = val2
                    if val1 < row[j]:
                        row[j] = val1
                        d[j][i] = val1

    sys.stdout.write('\n'.join(reversed(answers)))

if __name__ == '__main__':
    main()

