from math import comb

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        n = len(s)
        counts = [0] * (n + 1)
        prefix_ones = 0

        # Count each number less than s by the position of its first smaller bit.
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for extra_ones in range(remaining + 1):
                    counts[prefix_ones + extra_ones] += comb(remaining, extra_ones)
                prefix_ones += 1

        answer = 0
        for ones in range(1, n + 1):
            value = ones
            operations = 0
            while value > 1:
                value = value.bit_count()
                operations += 1
            # One operation turns the original number into its popcount.
            if operations + 1 <= k:
                answer += counts[ones]

        return answer % mod

