    out = [[[] for _ in range(26)] for _ in range(n)]
    for i, row in enumerate(g):
        for j, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - 97
                out[i][c].append(j)
                inc[j][c].append(i)
    d = [[-1] * n for _ in range(n)]
    q = deque()
    maxdist = 0
    for i in range(n):
        d[i][i] = 0
        q.append((i, i))
    for i in range(n):
        for c in range(26):
            for j in out[i][c]:
                if d[i][j] < 0:
                    d[i][j] = 1
                    maxdist = 1
                    q.append((i, j))
    while q:
        u, v = q.popleft()
        nd = d[u][v] + 2
        if nd >= maxdist:
            continue
        for c in range(26):
            a = inc[u][c]
            b = out[v][c]
            for x in a:
                dx = d[x]
                for y in b:
                    if dx[y] < 0:
                        dx[y] = nd
                        q.append((x, y))
    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in d))

