class S:
 def f(self,n,k):
  odds=list(range(1,n+1,2)); evens=list(range(2,n+1,2)); out=[]; need=None
  for pos in range(n):
   pool=odds+evens if need is None else (odds if need==1 else evens); pool.sort()
   for x in pool:
    p=x%2; ro=len(odds)-(p==1); re=len(evens)-(p==0); m=n-pos-1; start=1-p
    wo=(m+1)//2 if start==1 else m//2; we=m-wo
    c=math.factorial(ro)*math.factorial(re) if ro==wo and re==we else 0
    if k>c:k-=c
    else:
     out.append(x); (odds if p else evens).remove(x); need=1-p; break
   else:return []
  return out
